<div class="page-heading"><div><span class="eyebrow"><?= e(date('l, d F Y')) ?></span><h1>Your finances, in focus<span class="green">.</span></h1><p>A clear view of <?= can_manage()?'your business':'your expenses' ?>.</p></div><div class="heading-actions"><?php if(can_manage()): ?><a class="button" href="<?= e(url('entry',['type'=>'income'])) ?>"><?= icon('plus') ?>Add income</a><?php endif ?><a class="button primary" href="<?= e(url('entry',['type'=>'expense'])) ?>"><?= icon('plus') ?>Add expense</a></div></div>
