<div class="dashboard-grid"><section class="chart-section"><div class="section-heading"><div><h2>Income &amp; expenses</h2><p class="muted">Cash flow over the last 6 months</p></div><span class="subtle-label"><?= e(workspace()['currency']) ?></span></div><?php require ROOT.'/app/views/partials/chart.php'; ?></section><section class="spending-section"><div class="section-heading"><h2>Expense breakdown</h2></div><?php if(!$categories): ?><div class="empty-state compact"><?= icon('chart-no-axes-combined') ?><p>No paid expenses this month.</p></div><?php endif ?><?php foreach($categories as $i=>$cat): ?><div class="category-stat"><div><span><?= e($cat['name']) ?></span><strong><?= money($cat['amount']) ?></strong></div><progress class="category-progress shade-<?= $i%4 ?>" value="<?= (int)$cat['amount'] ?>" max="<?= max(1,(int)$summary['expenses']) ?>"></progress></div><?php endforeach ?><?php if(can_manage()&&workspace()['monthly_budget']>0): ?><div class="budget-summary"><span class="eyebrow">MONTHLY BUDGET</span><strong><?= money(max(0,(int)workspace()['monthly_budget']-(int)$summary['expenses'])) ?> remaining</strong><progress value="<?= min((int)$summary['expenses'],(int)workspace()['monthly_budget']) ?>" max="<?= workspace()['monthly_budget'] ?>"></progress><small><?= money($summary['expenses']) ?> of <?= money(workspace()['monthly_budget']) ?></small></div><?php endif ?></section></div>
